-- 작품에 Apple Music 앨범 링크를 채우고, 틀린 링크를 바꾼다. 자료와 규칙은
-- seed_pipeline/curation/piece-album-links-2026-11-08/.
-- 앨범 고르는 법: 트랙 이름에 작품번호(없으면 제목 구절)와 제목 낱말이 있고,
-- 앨범·아티스트에 작곡가 성이 있으며, 그런 트랙이 작품의 곡 수 이상인 앨범.
-- 검색 1위 앨범을 그냥 쓰지 않는다.
-- 빈칸을 채운 작품 3530개, 바꾼 작품 134개
-- (바꾼 것: 지금 링크의 앨범에 작품 트랙이 곡 수만큼 없거나, 링크가 트랙 하나인 것).
-- 빈칸은 빈칸일 때만, 바꿈은 지금 값이 그때 본 값과 같을 때만 쓴다. 두 번 넣어도 같다.

CREATE TEMPORARY TABLE tmp_piece_apple (
    piece_id INT NOT NULL PRIMARY KEY,
    old_url VARCHAR(500) NULL,
    url VARCHAR(500) NOT NULL
);

UPDATE pieces piece
JOIN tmp_piece_apple link ON link.piece_id = piece.id
SET piece.apple_music_url = link.url
WHERE (link.old_url IS NULL AND (piece.apple_music_url IS NULL OR piece.apple_music_url = ''))
    OR piece.apple_music_url = link.old_url;

DROP TEMPORARY TABLE tmp_piece_apple;
